loadSidebarNav(),initIcons(),initScrollReveal(),loadFooter(),(function(){const grid=document.getElementById("acGrid"),pending=document.getElementById("acPending"),pendingText=document.getElementById("acPendingText"),cell=(n,k,sub,empty)=>`<div class="ac-cell">
            <div class="ac-n${empty?" is-empty":""}">${escHTML(n)}</div>
            <div class="ac-k">${escHTML(k)}</div>
            <div class="ac-sub">${escHTML(sub)}</div>
        </div>`;fetch("/data/model-summary.json?v="+(typeof CACHE_BUSTER<"u"?CACHE_BUSTER:Date.now())).then(r=>r.ok?r.json():Promise.reject(new Error("unavailable"))).then(d=>{const graded=d.gameweeksGraded||0,fixtures=d.playerFixturesGraded||0,starters=d.startersGraded||0;if(!graded){grid.innerHTML=cell("\u2014","Gameweeks graded","Grading starts once a round has been played and scored",!0)+cell("\u2014","Player fixtures","Every player with a fixture is scored, not a sample",!0)+cell("\u2014","vs FPL\u2019s own forecast","Measured against ep_next at the deadline",!0)+cell("\u2014","vs points per game","The other baseline worth beating",!0),pendingText.innerHTML="<b>No rounds graded yet this season.</b> The job runs after every gameweek is final and writes its results here. Until then there is nothing to report, and we would rather say that than show you a zero.",pending.hidden=!1;return}const pct=v=>v==null?"\u2014":(v>0?"+":"")+(v*100).toFixed(1)+"%";grid.innerHTML=cell(String(graded),"Gameweeks graded","Written down before kick-off, scored once the round was final")+cell(fixtures.toLocaleString(),"Player fixtures scored","Every player with a fixture, not a sample")+cell(pct(d.vsEp),"Better than FPL\u2019s forecast",`Less squared error than ep_next, over ${starters} projected starters`)+cell(pct(d.vsPpg),"Better than points per game","The simplest baseline there is, on the same players"),d.provisional&&(pendingText.innerHTML=`<b>${graded===1?"One round":graded+" rounds"} graded so far.</b> Read these as early signals rather than a verdict \u2014 telling a real edge from a good week takes ten to fifteen rounds, and we would rather say so than let one afternoon speak for the season.`,pending.hidden=!1)}).catch(()=>{grid.innerHTML=cell("\u2014","Scoreboard unavailable","The results file could not be loaded just now",!0)})})();
